import json
R='/project1/glsl_test_6'
results={}
for c in op(R).children:
    results[c.name+'_type']=str(type(c))
    if 'glsl' in c.name.lower() and 'info' not in c.name.lower() and 'compute' not in c.name.lower():
        results['glsl_errors']=str(c.errors())
        results['outputattrs']=str(c.par.outputattrs.eval())
        results['numelems']=str(c.par.numelems.eval())
        results['computedat']=str(c.par.computedat.eval())
    if 'info' in c.name.lower():
        try:
            t=c.text
            results['info_dat_text']=str(t[:800]) if t else '(empty)'
        except Exception as e:
            results['info_dat_text']='err:'+str(e)
    if 'grid' in c.name.lower() or 'src' in c.name.lower():
        results['source_type']=str(type(c))
        results['source_pars']='rows='+str(c.par.rows.eval())+' cols='+str(c.par.cols.eval())
results['children_names']=[str(c.name) for c in op(R).children]
print(json.dumps(results))
